export const APIErrorName = 'APIError'

class ExtendableError<TData extends object = { [key: string]: unknown }> extends Error {
  data: TData

  readonly errorCode: string

  isOperational: boolean

  isPublic: boolean

  status: number

  constructor(errorCode: string, message: string, status: number, data: TData, isPublic: boolean) {
    super(message, {
      // show data in cause
      cause: data,
    })
    this.name = this.constructor.name
    this.errorCode = errorCode
    this.message = message
    this.status = status
    this.data = data
    this.isPublic = isPublic
    this.isOperational = true // This is required since bluebird 4 doesn't append it anymore.
    Error.captureStackTrace(this, this.constructor)
  }
}

/**
 * Class representing an API error.
 * @extends ExtendableError
 */
export class APIError<
  TData extends null | object = { [key: string]: unknown } | null,
  // @ts-expect-error - vestiges of when tsconfig was not strict. Feel free to improve
> extends ExtendableError<TData> {
  /**
